cards.solution:
class Produk {
  constructor(nama, harga) {
    this.nama = nama;
    this.harga = harga;
  }
  info() {
    return `${this.nama}: Rp${this.harga}`;
  }
}
class ProdukDigital extends Produk {
  unduh() {
    return `Mengunduh ${this.nama}`;
  }
}
const ebook = new ProdukDigital("E-book JS", 50000);
console.log(ebook.info());
console.log(ebook.unduh());
